import math
# R1 signed: S85=0.31273 (small+), S200=2.8925 (+). Fit S(TI)=M(1-(1+k)e^{-TI/T1})
def solve(k):
    def resid(T1): return 0.31273*(1-(1+k)*math.exp(-200/T1))-2.8925*(1-(1+k)*math.exp(-85/T1))
    lo,hi=90,400
    for _ in range(80):
        mid=(lo+hi)/2
        if resid(lo)*resid(mid)<=0: hi=mid
        else: lo=mid
    return (lo+hi)/2
for k in (0.5,0.7,0.8,0.9,1.0):
    T1=solve(k); null=T1*math.log(1+k)
    print("k=%.1f  T1=%.0f  nullTI=%.0f"%(k,T1,null))

