import math
k=1.0
def sig(T1,TI,TR,TE,M0):
    Epre = math.exp(-(TR-TI-TE/2)/T1)
    return M0 + (-k*M0*(1-Epre) - M0)*math.exp(-TI/T1)
def nullTI(T1,TR=1430,TE=8.4):
    g=lambda TI: sig(T1,TI,TR,TE,1.0)
    a,b=5.0,TR-TE/2; ga,gb=g(a),g(b)
    for _ in range(80):
        c=0.5*(a+b); gc=g(c)
        if ga*gc<=0: b=c;gb=gc
        else: a=c;ga=gc
    return 0.5*(a+b)
M0=3.994
# R1/R3: solve T1 from single point S at TI=100,TR=1430
def solveT1(S):
    h=lambda T1: sig(T1,100,1430,8.4,M0)-S
    # scan for sign changes
    ts=[120+t*40 for t in range(120)]
    for i in range(len(ts)-1):
        a,b=ts[i],ts[i+1]; ha,hb=h(a),h(b)
        if ha*hb<=0:
            for _ in range(60):
                c=0.5*(a+b); hc=h(c)
                if ha*hc<=0: b=c;hb=hc
                else: a=c;ha=hc
            return 0.5*(a+b)
    return None
