# AFI ratio S2/S1 vs T1 (single material, uniform B1, TR1=30,TR2=120, nominal FA=25 -> a unknown, assume a=25 as test)
import math
def s(E,a,TR):
    # Ernst: S = (1-E)/(1-E cos a)  (x M0 sin a); use sin a factor too
    return math.sin(math.radians(a))*(1-E)/(1-E*math.cos(math.radians(a)))
def ratio(T1,a):
    E1=math.exp(-30.0/T1); E2=math.exp(-120.0/T1)
    return s(E2,a,120)/s(E1,a,30)
for T1 in [400,800,1200,1600,2000,2500]:
